// X's GET /2/tweets accepts up to 100 ids per call.
const ids = $input.all().map((item) => String(item.json.reply_id || '')).filter(Boolean);
const chunks = [];
for (let i = 0; i < ids.length; i += 100) chunks.push(ids.slice(i, i + 100));
return chunks.map((chunk) => ({ json: { ids: chunk.join(','), id_list: chunk } }));

// One lookup response per chunk, in chunk order. A reply X answers with
// data[] is live. A resource-not-found error means it no longer exists on X
// (deleted, or its account is gone): that is the only case marked deleted.
// Any other error (e.g. a protected account) is recorded as checked, not deleted.
const chunks = $('Chunk Reply Ids').all();
const checked = [];
const deleted = [];
const otherErrors = [];
$input.all().forEach((item, index) => {
  const asked = (chunks[index] && chunks[index].json.id_list) || [];
  const errors = Array.isArray(item.json.errors) ? item.json.errors : [];
  for (const id of asked) checked.push(String(id));
  for (const err of errors) {
    const id = String(err.resource_id || err.value || '');
    if (!id) continue;
    if (String(err.type || '').endsWith('resource-not-found')) deleted.push(id);
    else otherErrors.push({ id, title: err.title || '', type: err.type || '' });
  }
});
return [{ json: { checked_ids: checked, deleted_ids: deleted, checked_count: checked.length, deleted_count: deleted.length, other_errors: otherErrors } }];
